import{_ as d,B as i,o,c as n,a,f as t,E as s,a8 as l}from"./chunks/framework.CNIpabDg.js";const y=JSON.parse('{"title":"WASM runtime","description":"Xila WASM command options, package features, WASI constraints, and browser capabilities.","frontmatter":{"layout":"doc","docType":"reference","description":"Xila WASM command options, package features, WASI constraints, and browser capabilities."},"headers":[],"relativePath":"reference/wasm-runtime.md","filePath":"reference/wasm-runtime.md","lastUpdated":1793145952000}'),c={name:"reference/wasm-runtime.md"};function u(p,e,m,h,b,g){const r=i("CodeReference");return o(),n("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1793145952000"},[e[7]||(e[7]=a("h1",{id:"wasm-runtime",tabindex:"-1"},[t("WASM runtime "),a("a",{class:"header-anchor",href:"#wasm-runtime","aria-label":'Permalink to "WASM runtime"'},"​")],-1)),a("p",null,[e[0]||(e[0]=t("The ",-1)),e[1]||(e[1]=a("code",null,"xila-wasm",-1)),e[2]||(e[2]=t(" Cargo package implements the Wasmi runtime and guest helper APIs. The native and browser examples mount its executable at ",-1)),e[3]||(e[3]=a("code",null,"/applications/executables/wasm",-1)),e[4]||(e[4]=t(". Sources: ",-1)),s(r,{repo:"applications",path:"executables/wasm/Cargo.toml"}),e[5]||(e[5]=t(" and ",-1)),s(r,{repo:"applications",path:"executables/wasm/src/host/main.rs"}),e[6]||(e[6]=t(".",-1))]),e[8]||(e[8]=l('<h2 id="command-syntax" tabindex="-1">Command syntax <a class="header-anchor" href="#command-syntax" aria-label="Permalink to &quot;Command syntax&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/applications/executables/wasm [--install] [--stack-size &lt;bytes&gt;] [--instruction-limit &lt;fuel&gt;] &lt;path&gt;</span></span></code></pre></div><p>The command runs in Xila&#39;s terminal. <code>&lt;path&gt;</code> must identify a regular guest file in the VFS; the loader reads the supplied path directly and does not perform <code>Current_directory</code> resolution. The guest receives its module path as its argument and the task environment as its environment.</p><table tabindex="0"><thead><tr><th>Argument/option</th><th>Default</th><th>Behavior</th></tr></thead><tbody><tr><td><code>&lt;path&gt;</code></td><td>Required</td><td>Guest module file path. Use an absolute VFS path.</td></tr><tr><td><code>--install</code></td><td>Off</td><td>Selects <code>__install: () -&gt; ()</code> instead of <code>_start: () -&gt; ()</code>. A missing or incorrectly typed export fails.</td></tr><tr><td><code>--stack-size</code></td><td>4096</td><td>Parsed as a stack size, but currently not applied by the runtime.</td></tr><tr><td><code>--instruction-limit</code></td><td>100,000</td><td>Nonzero fuel quantum used by resumable execution. Fuel is replenished after yielding; this is not a total instruction limit.</td></tr></tbody></table><h2 id="cargo-features" tabindex="-1">Cargo features <a class="header-anchor" href="#cargo-features" aria-label="Permalink to &quot;Cargo features&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>Purpose</th></tr></thead><tbody><tr><td><code>host</code></td><td>Wasmi interpreter and Xila executable integration; includes browser-hosted Xila.</td></tr><tr><td><code>guest</code></td><td>Guest helpers without the interpreter when default features are disabled.</td></tr><tr><td><code>graphics</code></td><td>Generated graphics wrappers and supported host imports.</td></tr><tr><td><code>c_bindings</code></td><td>Guest C wrappers/header generation; enables guest/graphics dependencies.</td></tr><tr><td><code>memory_32</code></td><td>32-bit guest-word translation configuration; default.</td></tr><tr><td><code>memory_64</code></td><td>Alternate 64-bit guest-word translation configuration; bundled applications remain wasm32.</td></tr><tr><td><code>default_guest</code></td><td><code>guest,graphics,c_bindings,memory_32</code>; emits <code>xila_graphics.h</code> in the build output directory.</td></tr></tbody></table><p>Default features are <code>host,memory_32</code>. Guest-only consumers must disable defaults. Core&#39;s <code>xila</code> package has neither a <code>host</code> nor a <code>wasm</code> feature; these runtime features belong to the <code>xila-wasm</code> package.</p><h2 id="results-and-errors" tabindex="-1">Results and errors <a class="header-anchor" href="#results-and-errors" aria-label="Permalink to &quot;Results and errors&quot;">​</a></h2><ul><li>WASI <code>proc_exit(0)</code> succeeds; a nonzero exit code becomes a runtime error.</li><li>Argument, file-kind, compilation, instantiation, missing-export, and execution failures are reported on stderr and return a nonzero executable result.</li><li>Standard streams are descriptors 0/1/2 in the per-execution WASI context. The root directory is preopened if available.</li><li>Graphics status and capability errors are defined in the <a href="./graphics-bindings.html">graphics reference</a>.</li></ul><h2 id="execution-limits" tabindex="-1">Execution limits <a class="header-anchor" href="#execution-limits" aria-label="Permalink to &quot;Execution limits&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>Current constraint</th></tr></thead><tbody><tr><td>Interpreter</td><td>Wasmi 2 with validation, memory64 support, and automatic portable/native dispatch as available.</td></tr><tr><td>Translation</td><td>Functions are translated eagerly before execution so fuel exhaustion cannot suspend lazy callee translation. This can increase startup work.</td></tr><tr><td>Scheduling</td><td>Fuel exhaustion and <code>sched_yield</code> yield cooperatively to the executor. Wasmi 2 meters input Wasm operators, so slice timing is not version-stable.</td></tr><tr><td><code>poll_oneoff</code></td><td>Up to 64 supported realtime/monotonic subscriptions. Invalid UTC does not prevent monotonic polling; file-descriptor readiness remains unsupported.</td></tr><tr><td>Startup clock</td><td>Uses the monotonic Embassy source; adjustable UTC is separate and can be unsynchronized.</td></tr><tr><td>WebAssembly start sections</td><td>Suspension is unsupported. WASI command guests should use exported <code>_start</code>.</td></tr><tr><td>WASI/graphics compatibility</td><td>Partial WASI coverage and a supported graphics subset, not full compatibility.</td></tr><tr><td>Graphics ABI</td><td>Guest and host must match the LVGL revision/configuration; only registry-supported wrappers are generated, with no capability negotiation yet.</td></tr></tbody></table><h2 id="browser-capabilities" tabindex="-1">Browser capabilities <a class="header-anchor" href="#browser-capabilities" aria-label="Permalink to &quot;Browser capabilities&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Browser example behavior</th></tr></thead><tbody><tr><td>Host target</td><td>Xila builds for <code>wasm32-unknown-unknown</code>; application guests build for <code>wasm32-wasip1</code>.</td></tr><tr><td>Storage APIs</td><td>Requires OPFS, <code>FileSystemFileHandle.createWritable</code>, and Web Locks on localhost/HTTPS.</td></tr><tr><td>Disk format</td><td>The selected disk is a 16 MiB MBR/LittleFS image local to the browser origin.</td></tr><tr><td>Disk names</td><td><code>xila_drive.img</code> remains the legacy/default image. New disks use <code>xila_YYYY-MM-DD.img</code> with numeric collision suffixes.</td></tr><tr><td>Disk management</td><td>The Xila Help panel lists, creates, selects, and removes managed images. The selected image is remembered for the origin.</td></tr><tr><td>Disk ownership</td><td>One Xila tab can hold a given disk&#39;s lifetime Web Lock. Different tabs may use different disks.</td></tr><tr><td>Disk switching</td><td>New writes stop, pending changes are saved, the current lock is released, and the page reloads on the selected image. An image open elsewhere cannot be removed.</td></tr><tr><td>Saves</td><td>At boot, every second when dirty, and on normal shutdown; synchronous flushes update the memory cache.</td></tr><tr><td>Memory</td><td>16 MiB selected-disk cache plus one temporary 16 MiB snapshot and browser buffering during saves. Guest/interpreter/graphics and embedded application bytes add further costs.</td></tr><tr><td>Fresh account</td><td><code>administrator</code> with an empty password; created only for a fresh disk. Existing accounts are restored.</td></tr><tr><td>Bundled guests</td><td>Calculator, Clock, Pixel Painter, Synth, Weather, and Text Editor are included in new locale-matched seeded images under <code>/applications/executables</code>; matching release guest artifacts are needed for image creation. Existing persistent disks are not upgraded automatically.</td></tr><tr><td>Guest upload</td><td>No general upload mechanism. Other guests must already be present in the VFS.</td></tr><tr><td>Networking</td><td>No Xila network manager; HTTP uses Fetch under CORS/browser restrictions and does not expose raw sockets.</td></tr></tbody></table><p>Browser-managed storage can be evicted or lost; abrupt termination can lose changes since the last completed save. See <a href="/explanation/browser-storage.html">Browser storage</a> for the durability model and <a href="/how-to/reset-browser-storage.html">Manage browser disks</a> for user-facing disk operations.</p><h2 id="related-documentation" tabindex="-1">Related documentation <a class="header-anchor" href="#related-documentation" aria-label="Permalink to &quot;Related documentation&quot;">​</a></h2><ul><li><a href="/how-to/build-guest.html">Build a guest</a> and <a href="/how-to/run-guest.html">run a guest</a>.</li><li><a href="/tutorials/browser.html">Run Calculator in the browser</a>.</li><li><a href="./graphics-bindings.html">Graphics bindings</a>, including the indexed-canvas helpers used by Pixel Painter.</li><li><a href="/explanation/architecture/executables/wasm.html">Wasmi execution model</a>.</li></ul>',16))])}const w=d(c,[["render",u]]);export{y as __pageData,w as default};
